"""Use the existing scientific Workspace; no second project implementation."""
import argparse,json,sys
from .workspace import Workspace
from .chemistry import Chemistry,invoke,ACTIONS

def main(argv=None):
    p=argparse.ArgumentParser()
    p.add_argument('--workspace',required=True)
    p.add_argument('action',choices=sorted(ACTIONS|{'chemistry.cancel','chemistry.receive-file'}))
    p.add_argument('payload',help='JSON file containing the original operation payload')
    args=p.parse_args(argv)
    try:
        ws=Workspace(args.workspace)
        with open(args.payload,encoding='utf-8') as f: value=json.load(f)
        if args.action=='chemistry.cancel': result=Chemistry(ws).request_cancel(value['run_id'])
        elif args.action=='chemistry.receive-file': result=Chemistry(ws).receive(value['path'])
        else: result=invoke(ws,args.action,value)
        print(json.dumps(result,ensure_ascii=False,indent=2,allow_nan=False));return 0
    except (ValueError,OSError,KeyError,TypeError) as exc:
        print(json.dumps({'error':type(exc).__name__,'message':str(exc)}),file=sys.stderr);return 2
if __name__=='__main__':raise SystemExit(main())

"""Reopen original chemistry selections and artifacts inside workspace receiving."""
from .chemistry import Chemistry
from .common import identifier, verify_file


def verify_all(workspace):
    service = Chemistry(workspace)
    cases = {}
    for saved in workspace._list('chemistry-cases'):
        case = service.get_case(saved['id'])
        cases[case['id']] = case
    for case in cases.values():
        if case.get('parent_id') and case['parent_id'] not in cases:
            raise ValueError('Chemical scenario is missing its original parent edition')
    runs = 0
    for path in sorted(service.root.glob('*/run.json')):
        key = identifier(path.parent.name)
        run = service.get_run(key)
        case = cases.get(run['case_id'])
        selection = run['selection']
        if (case is None or selection.get('case_id') != case['id']
                or selection.get('project_sha256') != case['project_sha256']):
            raise ValueError('Chemical analysis belongs to a different retained scenario')
        if run.get('calibrated_case_id') and run['calibrated_case_id'] not in cases:
            raise ValueError('Chemical analysis is missing its calibrated scenario')
        service._verified_artifacts(key, run)
        if run.get('checkpoint'):
            verify_file(service.root / key, run['checkpoint'])
        runs += 1
    return {'cases': len(cases), 'runs': runs}

"""Small current views of complete original delivery records."""
from .common import digest

REPORT_ROLES = (
    "report", "report_html", "report_markdown", "report_data", "report_model",
    "client_report", "client_report_html", "client_report_markdown",
    "client_report_data", "client_report_model",
)


def delivery_view(record):
    """One revision and report availability shared by polling and inspection."""
    files = record.get("files") or {}
    selection = record.get("selection") or {}
    return {
        "schema": "upstate.delivery-view/v1",
        "revision": digest(record),
        "report_roles": [role for role in REPORT_ROLES if role in files],
        "report_edition": "|".join(str(selection.get(selected) or record.get(saved) or "")
                                  for selected, saved in (
                                      ("client_report_edition", "report_edition"),
                                      ("report_renderer_version", "report_renderer_version"),
                                      ("client_companion_edition", "client_companion_edition"))),
    }

"""One monitoring command surface used by the original queued operator and CLI."""
from __future__ import annotations
import inspect
from .monitoring_common import ContractError
from .monitoring_workspace import MonitoringWorkspace

READS = {"context.catalog", "context.list", "context.get", "context.preview", "list", "get", "frontier.progress", "campaign.get", "campaign.list", "campaign.history", "capabilities", "source.catalog"}
WRITES = {"context.prepare", "context.export", "network.import", "design", "frontier", "campaign.create", "campaign.revise", "campaign.event", "export"}

def invoke(workspace, action, params, *, export_root=None):
    if not isinstance(params, dict): raise ContractError("Monitoring parameters must be a JSON object")
    service = MonitoringWorkspace(workspace, export_root=export_root)
    if action.startswith("context."):
        from . import monitoring_observed_context as observed
        functions = {"context.catalog": observed.catalog, "context.list": observed.list_saved,
                     "context.get": observed.inspect, "context.preview": observed.preview,
                     "context.prepare": observed.prepare, "context.export": observed.export_context}
        if action not in functions:
            raise ContractError("Unknown monitoring context action")
        options = dict(params)
        if action == "context.export": options["export_root"] = export_root
        return functions[action](workspace, **options)
    commands = {
        "network.import": service.import_network, "list": service.list, "get": service.get,
        "design": service.design, "frontier": service.frontier, "frontier.progress": service.frontier_progress,
        "campaign.create": service.create_campaign, "campaign.get": service.campaign,
        "campaign.list": service.campaigns, "campaign.revise": service.revise_campaign,
        "campaign.event": service.field_event, "campaign.history": service.history, "export": service.export,
    }
    if action == "capabilities":
        return {"schema": "eco.monitoring.api/1.2", "commands": sorted(READS | WRITES),
                "native_write_route": "POST /api/actions", "native_read_route": "GET /api/monitoring",
                "action_prefix": "monitoring.", "geometry": "complete retained native vectors projected to WGS84",
                "source_selection": "source edition ID plus named entry ID", "default_coverage": "local",
                "editable_receiving": "original Workspace.backup and model.portable.restore"}
    if action == "source.catalog":
        if params: raise ContractError("Source catalog takes no parameters")
        if not callable(getattr(workspace, "sources", None)): return {"collections": []}
        return {"collections": [{"id": c["id"], "title": c.get("title", c["id"]), "entries": [
            {"id": e["id"], "title": e.get("title", e["id"]), "layer": e.get("layer"),
             "sha256": e["body"]["sha256"], "filename": e["body"]["filename"]}
            for e in c["entries"] if e.get("kind") == "vector"]} for c in workspace.sources()]}
    function = commands.get(action)
    if function is None: raise ContractError(f"Unknown monitoring action: {action}")
    try: inspect.signature(function).bind(**params)
    except TypeError as exc: raise ContractError(str(exc)) from exc
    return function(**params)

"""Command-line conservation coalition workflow over retained native runs."""
from __future__ import annotations

import argparse
import json
from pathlib import Path
import sys

from .common import atomic_json
from .native_interactions import (
    analyze_plan, apply_plan, get_plan, get_result, list_plans, preview, save_plan,
)
from .workspace import Workspace


def _selection(filename):
    if filename == "-":
        value = json.load(sys.stdin)
    else:
        with Path(filename).open("r", encoding="utf-8-sig") as stream:
            value = json.load(stream)
    if not isinstance(value, dict):
        raise ValueError("The selection must be a JSON object")
    return value


def _parser():
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--workspace", type=Path, default=argparse.SUPPRESS,
                        help="Existing retained Upper Savannah workspace")
    common.add_argument("--output", type=Path, default=argparse.SUPPRESS,
                        help="Write exact JSON to this file instead of stdout")
    parser = argparse.ArgumentParser(
        description="Prepare and analyze native conservation action coalitions.",
        parents=[common])
    commands = parser.add_subparsers(dest="command", required=True)
    for name in ("preview", "plan"):
        command = commands.add_parser(name, parents=[common])
        command.add_argument(
            "--selection", required=True,
            help="Selection JSON file; use '-' to read the object from stdin")
    commands.add_parser("list", parents=[common])
    for name in ("show", "apply", "analyze"):
        command = commands.add_parser(name, parents=[common])
        command.add_argument("plan_id")
        if name == "apply":
            command.add_argument(
                "--run-models", action="store_true",
                help="Resume original native NDR/SDR runs and analyze their completed outputs")
    command = commands.add_parser("result", parents=[common])
    command.add_argument("result_id")
    return parser


def main(argv=None):
    parser = _parser()
    args = parser.parse_args(argv)
    if not hasattr(args, "workspace"):
        parser.error("--workspace is required")
    try:
        workspace = Workspace(args.workspace)
        if args.command == "preview":
            value = preview(workspace, _selection(args.selection))
        elif args.command == "plan":
            value = save_plan(workspace, _selection(args.selection))
        elif args.command == "list":
            value = list_plans(workspace)
        elif args.command == "show":
            value = get_plan(workspace, args.plan_id)
        elif args.command == "apply":
            value = apply_plan(workspace, args.plan_id, run_models=args.run_models)
        elif args.command == "analyze":
            value = analyze_plan(workspace, args.plan_id)
        elif args.command == "result":
            value = get_result(workspace, args.result_id)
        else:
            raise ValueError("Unknown command")
        if hasattr(args, "output"):
            atomic_json(args.output, value)
        else:
            print(json.dumps(value, ensure_ascii=False, indent=2, allow_nan=False))
        return 1 if isinstance(value, dict) and value.get("state") == "failed" else 0
    except (ValueError, OSError, RuntimeError, KeyError) as exc:
        print(json.dumps({
            "error": type(exc).__name__, "message": str(exc),
            "command": args.command,
        }, ensure_ascii=False), file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

"""Executed native-model versions, preserving retained per-stage provenance."""
from __future__ import annotations

from copy import deepcopy
from .model_selection import MODEL_OUTPUTS, run_models

POLICY = "completed_stage_runtime_else_observed_run_else_labeled_requested_legacy"


def _text(value):
    return value.strip() if isinstance(value, str) and value.strip() else None


def native_version(run):
    """Retain the historical run-level declaration and last observed runtime."""
    requested = _text(run.get("selection", {}).get("invest_version"))
    observed = _text((run.get("runtime") or {}).get("version"))
    return {"requested": requested, "observed": observed,
            "comparison_version": observed or requested,
            "basis": "observed_runtime" if observed else "requested_legacy" if requested else "unavailable",
            "differs_from_requested": bool(observed and requested and observed != requested)}


def model_versions(run, models=None):
    """Read each completed model's execution source before run-level fallbacks."""
    selected = tuple(models) if models is not None else run_models(run)
    run_version = native_version(run)
    result = {}
    for model in selected:
        if model not in MODEL_OUTPUTS:
            raise ValueError("Choose an original native model.")
        stage = (run.get("stages") or {}).get(model) or {}
        stage_version = _text((stage.get("runtime") or {}).get("version")) if stage.get("completed_at") else None
        effective = stage_version or run_version["comparison_version"]
        result[model] = {
            "model": model, "comparison_version": effective,
            "basis": "completed_stage_runtime" if stage_version else
                     "observed_run_fallback" if run_version["observed"] else run_version["basis"],
            "observed_stage_version": stage_version,
            "observed_run_version": run_version["observed"],
            "requested_version": run_version["requested"],
            "differs_from_requested": bool(effective and run_version["requested"] and
                                            effective != run_version["requested"]),
            "stage_completed_at": stage.get("completed_at"),
            "reused_from": deepcopy(stage.get("reused_from")),
        }
    return result


def models_for_outputs(outputs):
    selected = set(outputs)
    return tuple(model for model, names in MODEL_OUTPUTS.items() if selected.intersection(names))


def comparison_versions(runs, models):
    """Resolve a per-common-model cohort without flattening mixed executed stages."""
    if not runs:
        raise ValueError("Choose retained native runs for this comparison.")
    selected = tuple(models)
    if not selected:
        raise ValueError("Choose at least one common native model.")
    by_run = {run["id"]: model_versions(run, selected) for run in runs}
    baseline = by_run[runs[0]["id"]]
    for run_id, versions in by_run.items():
        for model in selected:
            value = versions[model]["comparison_version"]
            if not value:
                raise ValueError("Native " + model.upper() + " run " + run_id +
                                 " has no completed-stage, observed-run or retained requested version.")
            if value != baseline[model]["comparison_version"]:
                raise ValueError("Compared " + model.upper() + " execution versions differ: " +
                                 str(baseline[model]["comparison_version"]) + " versus " + str(value) +
                                 " for run " + run_id + ".")
    return {"policy": POLICY, "models": list(selected),
            "versions": {model: baseline[model]["comparison_version"] for model in selected},
            "runs": by_run}

"""Core operator catalogues over the original retained Workspace records.

These readers are opt-in; full model record APIs keep their original behavior.
Changed immutable records pass the same content-identity check as Workspace._get.
"""
from __future__ import annotations

from .common import digest, identifier
from .record_catalog import ProjectedFileCache


def observation_summary(value):
    result = dict(value)
    result["row_count"] = len(result["rows"])
    result.pop("rows")
    return result


def run_summary(value):
    """Keep native stage presence for programme checks and original list metadata."""
    result = dict(value)
    stages = value.get("stages", {})
    retained = {
        name: {key: item for key, item in stage.items()
               if key in {"started_at", "completed_at", "reused_from", "reused_at", "runtime"}}
        for name, stage in stages.items()
    }
    result["stage_summary"] = {
        name: {**retained[name], "file_count": len(stage.get("files", {}))}
        for name, stage in stages.items()
    }
    # ProgrammeActivity validates stage presence/completion against artifacts.
    # Its actual execution locks are still inspected on every response.
    result["stages"] = retained
    return result


class OperatorCatalogue:
    """One bounded cache shared by the core collection readers of a Workspace."""

    def __init__(self, root):
        self.root = root
        self.cache = ProjectedFileCache()

    def immutable(self, kind, visited):
        folder = self.root / kind
        paths = sorted(folder.glob("*.json")) if folder.exists() else []
        visited.extend(paths)
        rows = []
        for path in paths:
            key = identifier(path.stem)

            def project(value, key=key):
                if digest(value) != key:
                    raise ValueError("Retained " + kind + " item changed")
                record = {**value, "id": key}
                return observation_summary(record) if kind == "observations" else record

            rows.append(self.cache.read(path, project))
        return rows

    def mutable(self, kind, filename, visited):
        paths = sorted((self.root / kind).glob("*/" + filename))
        visited.extend(paths)
        project = run_summary if kind == "runs" else lambda value: value
        return [self.cache.read(path, project) for path in paths]

    def finish(self, visited):
        self.cache.retain_paths(visited)

"""One request contract shared by the CLI and the original product adapter."""
from __future__ import annotations
from .model import Project, ModelError
from .solver import simulate, attribute_sources
from .inference import sensitivity, fit_observations, design_monitoring, uncertainty

MODES = ('simulate', 'attribute', 'sensitivity', 'calibrate', 'monitoring', 'uncertainty')

def execute(project: Project | dict, request: dict, *, cancelled=None, progress=None,
            checkpoint=None, resume=None) -> dict:
    p = Project(project) if isinstance(project, dict) else project
    if not isinstance(request, dict):
        raise ModelError('analysis request must be an object')
    mode = request.get('mode', 'simulate')
    if mode not in MODES:
        raise ModelError('mode must be one of ' + ', '.join(MODES))
    if mode == 'simulate':
        return simulate(p, request.get('sample_days'), targets=request.get('targets'),
                        cancelled=cancelled, progress=progress, checkpoint=checkpoint, resume=resume).result()
    if mode == 'attribute':
        return attribute_sources(p, request.get('sample_days'), targets=request.get('targets'),
                                 cancelled=cancelled, progress=progress)
    parameters = request.get('parameters', [])
    observations = request.get('observations', [])
    if mode == 'sensitivity':
        return sensitivity(p, parameters, observations, cancelled=cancelled)
    if mode == 'calibrate':
        return fit_observations(p, parameters, observations,
                                loss=request.get('loss', 'linear'),
                                max_evaluations=request.get('max_evaluations', 200),
                                cancelled=cancelled, progress=progress)
    if mode == 'monitoring':
        return design_monitoring(p, parameters, observations, count=request.get('count'),
                                 prior_precision=request.get('prior_precision'), cancelled=cancelled)
    return uncertainty(p, parameters, observations, draws=request.get('draws'), seed=request.get('seed'),
                       distributions=request.get('distributions', []), correlation=request.get('correlation'),
                       cancelled=cancelled, progress=progress)

#!/usr/bin/env python3
"""Prepare, compare and export retained Upper Savannah receiving waters."""
from __future__ import annotations
import argparse
import json
from pathlib import Path
import sys
if __package__ in (None, ""):
    sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
    __package__ = "model"
from .common import read_json
from .workspace import Workspace
from . import receiving_waters, receiving_water_delivery


def parser():
    command = argparse.ArgumentParser(description=__doc__)
    command.add_argument("--workspace", type=Path, required=True)
    operations = command.add_subparsers(dest="operation", required=True)
    for name, help_text in (
        ("prepare", "Create a source-only receptor plan"),
        ("profile", "Use the shared utility-focus receptor profile"),
        ("analyze", "Analyze completed original baseline and land-cover runs"),
        ("build", "Resolve a plan, analyze runs and export a complete receiving-water delivery"),
    ):
        selected = operations.add_parser(name, help=help_text)
        selected.add_argument("selection", type=Path)
        if name == "profile":
            selected.add_argument("--grid-id")
        if name == "build":
            selected.add_argument("--output-dir", type=Path)
    for name in ("plan", "analysis", "layers"):
        operations.add_parser(name).add_argument("id")
    listing = operations.add_parser("list")
    listing.add_argument("kind", choices=("plans", "analyses", "all"), default="all", nargs="?")
    export = operations.add_parser("export")
    export.add_argument("analysis_id")
    export.add_argument("output_dir", type=Path)
    return command


def main(argv=None):
    args = parser().parse_args(argv)
    workspace = Workspace(args.workspace)
    progress = lambda value: print(json.dumps(value, sort_keys=True), file=sys.stderr, flush=True)
    if args.operation == "prepare":
        result = receiving_waters.prepare(workspace, read_json(args.selection))
    elif args.operation == "profile":
        result = receiving_waters.prepare_receptor_spec(
            workspace, read_json(args.selection), grid_id=args.grid_id,
        )
    elif args.operation == "analyze":
        result = receiving_waters.analyze(workspace, read_json(args.selection), progress=progress)
    elif args.operation == "build":
        selection = read_json(args.selection)
        result = receiving_water_delivery.selected_analysis(workspace, selection, progress=progress)
        if result is None:
            raise ValueError("The build selection requires its receiving_waters source plan or analysis")
        if args.output_dir:
            result = receiving_water_delivery.export(workspace, result["id"], args.output_dir)
    elif args.operation == "plan":
        result = receiving_waters.inspect_plan(workspace, args.id)
    elif args.operation == "analysis":
        result = receiving_waters.inspect(workspace, args.id)
    elif args.operation == "layers":
        result = receiving_waters.delivery_layers(workspace, args.id)
    elif args.operation == "export":
        result = receiving_water_delivery.export(workspace, args.analysis_id, args.output_dir)
    else:
        result = {}
        if args.kind in ("plans", "all"):
            result["plans"] = receiving_waters.list_plans(workspace)
        if args.kind in ("analyses", "all"):
            result["analyses"] = receiving_waters.list_analyses(workspace)
    print(json.dumps(result, ensure_ascii=False, allow_nan=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

