import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import {fileURLToPath} from "node:url";
import {compute} from "./compute.mjs";
const here=path.dirname(fileURLToPath(import.meta.url));
const root=path.resolve(process.argv[2]||path.join(here,".."));
const destination=path.resolve(process.argv[3]||here);
const receipt=JSON.parse(fs.readFileSync(path.join(here,"inputs.json"),"utf8"));
const files={};
for(const input of receipt.inputs){
 const body=fs.readFileSync(path.join(root,input.path));
 if(body.length!==input.bytes||crypto.createHash("sha256").update(body).digest("hex")!==input.sha256)throw Error("Original input differs: "+input.path);
 files[input.path]=body.toString("utf8");
}
const result=compute(files);fs.mkdirSync(destination,{recursive:true});
const hashes={};
for(const [name,content] of Object.entries(result.files)){
 const body=Buffer.from(content);const target=path.join(destination,name);
 if(fs.existsSync(target)&&!fs.readFileSync(target).equals(body))throw Error("Existing calculated edition differs: "+name);
 if(!fs.existsSync(target))fs.writeFileSync(target,body,{flag:"wx"});
 hashes[name]={bytes:body.length,sha256:crypto.createHash("sha256").update(body).digest("hex")};
}
console.log(JSON.stringify({schema:"upstate.nutrient-flow-replay/v1",source_root:root,output:destination,outputs:hashes},null,2));

#!/usr/bin/env node
import {readFile, writeFile, mkdir, rename} from "node:fs/promises";
import {resolve, dirname, isAbsolute, relative, sep} from "node:path";
import {fileURLToPath} from "node:url";
import {createHash} from "node:crypto";
import {flowBuild} from "./hydrology_core.mjs";

const root = dirname(fileURLToPath(import.meta.url));
const args = process.argv.slice(2);
if (args.length !== 2 || args[0] !== "--output-dir") {
  throw new Error("Usage: node rebuild_hydrology.mjs --output-dir OUTPUT_DIRECTORY");
}
const output = resolve(args[1]);
const digest = data => createHash("sha256").update(data).digest("hex");
const inside = (base, name) => {
  if (isAbsolute(name) || name.includes("\\") || name.includes("\0")) throw new Error("Use a relative source path");
  const path = resolve(base, name), rel = relative(base, path);
  if (!rel || rel === ".." || rel.startsWith(".." + sep) || isAbsolute(rel)) throw new Error("Source path leaves its edition");
  return path;
};
const index = JSON.parse(await readFile(resolve(root, "inputs.json"), "utf8"));
if (index.schema !== "upstate.observed-hydrology-inputs/v1") throw new Error("Select the observed hydrology input index");
const originals = [];
for (const source of index.originals) {
  const data = await readFile(inside(root, source.path));
  if (data.length !== source.bytes || digest(data) !== source.sha256) throw new Error("Original source changed: " + source.path);
  originals.push({...source, text: data.toString("utf8")});
}
const result = flowBuild({...index, originals});
const expected = new Map(index.derived_files.map(x => [x.path, x]));
if (result.files.length !== expected.size) throw new Error("Generated file set differs");
const ready = [];
for (const file of result.files) {
  const data = Buffer.from(file.text, "utf8"), reference = expected.get("derived/" + file.path);
  if (!reference || data.length !== reference.bytes || digest(data) !== reference.sha256) throw new Error("Derived output differs: " + file.path);
  ready.push({path: inside(output, file.path), data});
}
for (const item of ready) {
  await mkdir(dirname(item.path), {recursive: true});
  const temp = item.path + ".partial-" + process.pid;
  await writeFile(temp, item.data);
  await rename(temp, item.path);
}
console.log(JSON.stringify({output, original_files: originals.length, generated_files: ready.length, coverage: result.coverage}, null, 2));

"""Assessment geographic-context extension for the maintained operator queue."""
from pathlib import Path
from model import assessment_context as model
from model.common import identifier, relative_file

ACTIONS=frozenset(("assessment.context.build","assessment.context.receive",
                   "assessment.context.parcels","assessment.context.receive_parcels"))

class AssessmentContext:
    def __init__(self,operator,fault):
        self.operator,self.Fault=operator,fault

    def state(self,workspace_key):
        ws=self.operator.ws(workspace_key)
        return [{key:row.get(key) for key in ("id","title","summary","created_at")}
                for row in ws._list(model.KIND)]

    def verify_workspace(self,workspace):
        return model.verify_workspace(workspace)

    def edition(self,workspace_key,key,complete=True,parcels=False):
        ws=self.operator.ws(workspace_key)
        inspect=model.inspect_parcels if parcels else model.inspect
        row=inspect(ws,identifier(key),include_result=complete)
        row["_downloads"]=[self.operator._ticket(workspace_key,relative_file(ws.root,item["path"]),
                           item,item.get("label") or Path(item["path"]).name) for item in row["files"]]
        return row

    def read(self,workspace_key,operation,payload=None):
        value=payload or {};ws=self.operator.ws(workspace_key)
        if operation=="catalog":
            return model.catalog(ws)
        if operation=="options":
            return model.options(ws,identifier(value.get("geography_id")))
        if operation in ("edition","parcels"):
            return self.edition(workspace_key,value.get("id"),parcels=operation=="parcels")
        raise self.Fault("ASSESSMENT_CONTEXT_READ","Choose a registered context operation.",422)

    def item(self,workspace_key,payload):
        return self.edition(workspace_key,payload.get("id") or payload.get("key"))

    def parcel_item(self,workspace_key,payload):
        return self.edition(workspace_key,payload.get("id") or payload.get("key"),parcels=True)

    def invoke(self,task):
        action=task.get("action");value=task.get("payload") or {}
        ws=self.operator.ws(task["workspace"])
        if action=="assessment.context.build":
            result=model.build(ws,value.get("selection",value))
        elif action in ("assessment.context.receive","assessment.context.receive_parcels"):
            upload=self.operator.upload(identifier(value.get("upload_id")))
            receive=model.receive_parcels if action.endswith("receive_parcels") else model.receive
            result=receive(ws,upload["path"],max_extracted_bytes=self.operator.extraction_limit)
        elif action=="assessment.context.parcels":
            result=model.parcel_associations(ws,identifier(value.get("context_id")),
                                            identifier(value.get("study_id")))
        else:
            raise self.Fault("ASSESSMENT_CONTEXT_ACTION","Choose a registered context action.",422)
        return {key:result[key] for key in ("id","title","build_id","summary","source_collection_id",
                "source_id","context_source_binding","context_id","study_id","received_from") if key in result}

    def decorate_task(self,task):
        if task.get("action") not in ACTIONS or task.get("state")!="complete":
            return task
        result=task.get("result") or {}
        if result.get("id"):
            parcels=task["action"] in ("assessment.context.parcels","assessment.context.receive_parcels")
            row=self.edition(task["workspace"],result["id"],complete=False,parcels=parcels)
            task.setdefault("_downloads",[]).extend(row["_downloads"])
            task["_assessment_context"]={"id":row["id"],"view":"assessment-context","parcels":parcels}
        return task

"""Chemical analysis on the original Operator's workspace, queue and downloads."""
from __future__ import annotations
from copy import deepcopy
from model.chemistry import Chemistry, ACTIONS, invoke
from model.common import digest
READS = {'catalog', 'case', 'run', 'page'}

class ChemistryOperations:
    def __init__(self, operator, fault):
        self.operator, self.Fault = operator, fault
    def manager(self, workspace):
        return Chemistry(self.operator.ws(workspace))
    def _decorate(self, workspace, value):
        result = deepcopy(value)
        ws = self.operator.ws(workspace)
        if isinstance(result, dict):
            # Native run descriptors are relative to that run; the original
            # download registrar takes descriptors relative to ws.root.
            files = deepcopy(result)
            if result.get('schema') == 'upstate.chemistry-run/v1':
                for item in files.get('artifacts', []):
                    item['path'] = 'chemistry-runs/' + result['id'] + '/' + item['path']
            result['_downloads'] = self.operator._files(workspace, files, ws.root)
        return result
    def read(self, workspace, operation, payload):
        m = self.manager(workspace)
        if operation == 'catalog':
            value = m.catalog()
            # Compact operator state intentionally omits full source entries.
            value['sources'] = [
                {'id': collection['id'], 'title': collection['title'],
                 'entries': [{'id': entry['id'], 'title': entry.get('title', entry['id']),
                              'kind': entry.get('kind')} for entry in collection['entries']]}
                for collection in m.ws._list('sources')]
        elif operation == 'case': value = m.get_case(payload['case_id'])
        elif operation == 'run': value = m.get_run(payload['run_id'])
        elif operation == 'page':
            value = m.result_page({**payload, 'offset':int(payload.get('offset') or 0),
                                  'limit':int(payload.get('limit') or 200)})
        else: raise self.Fault('CHEMISTRY_VIEW', 'Choose a chemical-analysis view.', 404)
        return {'workspace_key':workspace, **self._decorate(workspace, value)}
    def cancel(self, workspace, payload):
        # This signal must bypass the serial worker that is executing the run.
        return self.manager(workspace).request_cancel(payload['run_id'])
    def invoke(self, task):
        workspace = task['workspace']
        def progress(value):
            # Preserve the original queued task identity and progress store.
            task['chemistry_progress'] = value
            # The original Operator remains the only task writer. Native run
            # progress is persisted by model.chemistry and read by decorate_task.
        value = invoke(self.operator.ws(workspace), task['action'], task['payload'], progress_hook=progress)
        return self._decorate(workspace, value)
    def decorate_task(self, task):
        if task.get('action') not in ACTIONS: return task
        result = deepcopy(task)
        if task.get('action')=='chemistry.run':
            try:
                manager=self.manager(task['workspace'])
                case=manager.get_case(task['payload']['case_id'])
                from model.chemistry import ENGINE_VERSION
                key=digest({'case_id':case['id'],'project_sha256':case['project_sha256'],
                            'request':task['payload'].get('request',{}),'engine_version':ENGINE_VERSION})
                native=manager.get_run(key)
                result['chemistry_run_id']=key
                result['chemistry_progress']=native.get('progress',{})
            except (FileNotFoundError,KeyError,ValueError):pass
        if result.get('state') == 'complete' and isinstance(result.get('result'), dict):
            result['result'] = self._decorate(task['workspace'], result['result'])
            result['_downloads'] = result['result'].get('_downloads', [])
        return result

"""Bind project transfer and recovery to the maintained operator extension host."""
from pathlib import Path

from model.common import read_json
from project_continuity import ProjectContinuity


class ProjectContinuityExtension:
    def __init__(self, operator, fault):
        self.operator = operator
        self.service = ProjectContinuity(operator, fault, supported_actions=())

    def _current(self):
        # The original host assigns operator.extensions after load() finishes.
        # Resolve the union at invocation so later installed desks are included.
        registry = self.operator.extensions
        self.service.supported_actions = (
            set(registry._builtin_actions) | set(registry.accepted_actions))
        return self.service

    def invoke(self, task):
        return self._current().invoke(task)

    def read(self, workspace_key, operation, payload):
        return self._current().read(workspace_key, operation, payload)

    def state(self, workspace_key):
        service = self._current()
        return {"transfers": service.list(workspace_key),
                "accepted_actions": sorted(service.supported_actions)}

    def decorate_task(self, task):
        return self._current().decorate_task(task)

    def verify_workspace(self, workspace):
        # Restore verification receives the actual Workspace before registration.
        # No operator workspace key or action invocation is needed here.
        transfers = []
        directory = Path(workspace.root) / "project-transfers"
        for path in sorted(directory.glob("*.json")):
            if path.stem == "HEAD":
                continue
            record = self.service._verify(workspace, read_json(path))
            transfers.append(record["id"])
        return {"project_id": workspace.project["id"], "transfers": transfers}


def create(operator, fault):
    return ProjectContinuityExtension(operator, fault)

"""Join complete project transfer and recovery to the shared operator registry."""
from project_continuity import ACTIONS, READS, ProjectContinuity


def create(context):
    service = ProjectContinuity(context.operator, context.Fault,
                               supported_actions=context.actions)

    def current():
        # Read the registry's current union, including later-loaded components.
        service.supported_actions = context.actions
        return service

    def invoke(task):
        return current().invoke(task)

    def reader(operation):
        def read(workspace_key, query):
            return current().read(workspace_key, operation, query)
        return read

    def state(workspace_key):
        return {"project_transfers": current().list(workspace_key),
                "project_transfer_actions": sorted(context.actions)}

    def decorate_task(task):
        return current().decorate_task(task)

    return {"actions": {name: invoke for name in ACTIONS},
            "reads": {name: reader(name) for name in READS},
            "state": state,
            "decorate_task": decorate_task}

