"""Authenticated original-operator continuation for a retained scenario analysis."""
from model import scenario_analysis_delivery

def read(operator, workspace_key, operation, payload):
    if operation != "selection":
        raise ValueError("Choose the retained scenario-analysis delivery selection")
    workspace = operator.ws(workspace_key)
    value = scenario_analysis_delivery.describe(
        workspace, (payload or {}).get("analysis_id") or (payload or {}).get("id"))
    return {**value, "workspace_key": workspace_key}

"""Bind source refresh to the existing Operator, Handler and durable task queue.

install(vars(server)) composes the maintained server in place before start_server.
The handler reuses the original Host/Origin policy, session bearer and Workspace
registry. Tasks retain the original operation identity and resume through _invoke.
"""
from __future__ import annotations
from functools import wraps
from urllib.parse import parse_qs, urlsplit
import uuid

from model.common import identifier, held
from model.source_refresh import SourceRefresh
from source_refresh import extend_handler

ACTION = 'source-refresh.apply'


def install(namespace):
    """Register once; delegate every other original route and action unchanged."""
    if namespace.get('_source_refresh_registered'):
        return namespace['Handler']
    original = namespace['Operator']
    invoke = original._invoke

    @wraps(invoke)
    def with_refresh(self, task):
        if task['action'] == 'workspace.backup' and task['payload'].get('source_refresh_plan_id'):
            refresh = SourceRefresh(self.ws(task['workspace']))
            key = identifier(task['payload']['source_refresh_plan_id'])
            refresh._validate_plan(refresh.get(key))
            with held(refresh._state_path(key).parent / '.refresh.lock'):
                return invoke(self, task)
        if task['action'] != ACTION:
            return invoke(self, task)
        value = task['payload']
        execute = value.get('execute_runs', True)
        if not isinstance(execute, bool):
            raise ValueError('execute_runs must be a boolean')
        return SourceRefresh(self.ws(task['workspace'])).apply(
            identifier(value['plan_id']), execute_runs=execute).state

    def selected(handler):
        value = getattr(handler, '_source_refresh_payload', None)
        if value is not None:
            return value.get('workspace') or handler.app.primary
        query = parse_qs(urlsplit(handler.path).query)
        values = query.get('workspace', [handler.app.primary])
        if len(values) != 1:
            raise ValueError('Choose one original workspace')
        return values[0]

    def workspace(handler):
        return handler.app.ws(selected(handler))

    def authorize(handler, write):
        if '/api/' in urlsplit(handler.path).path:
            handler.authorized()
        else:
            handler.check_host()
        return True

    def submitter(handler):
        def submit(action, payload, _callable):
            incoming = getattr(handler, '_source_refresh_payload', {})
            operation = incoming.get('operation_id') or uuid.uuid4().hex
            return handler.app.submit(selected(handler), action, payload, operation)
        return submit

    base = extend_handler(namespace['Handler'], workspace,
                          submit_for_handler=submitter, authorize_for_handler=authorize)

    class NativeSourceRefreshHandler(base):
        def _refresh_error(self, error):
            # Preserve the original native fault code/status and JSON structure.
            return self.fail(error)

    original._invoke = with_refresh
    namespace['ACTIONS'].add(ACTION)
    namespace['Handler'] = NativeSourceRefreshHandler
    namespace['_source_refresh_registered'] = True
    return NativeSourceRefreshHandler

/** Original reach chemistry, with one retained editor per native workspace. */
import {attachChemistry} from './chemistry.mjs';

const workspaceKey = value => value?.workspace_key ?? value?.workspace ?? value?.data?.workspace_key;
export function attachNativeChemistry(host) {
  const desks = new Map();
  let active = null;
  function currentKey() {
    const key = workspaceKey(host.getState());
    if (!key) throw Error('Open an original scientific workspace.');
    return key;
  }
  function desk(key) {
    if (desks.has(key)) return desks.get(key);
    const panel = document.createElement('div');
    let snapshot = host.getState(), busy = false, completed = null, updating = false, ready;
    const state = () => {
      const live = host.getState();
      if (workspaceKey(live) === key) snapshot = live;
      return snapshot;
    };
    const controller = attachChemistry({
      ...host, getState: state,
      endpoint: (path, values = {}) => path + '?' + new URLSearchParams({...values, workspace: key}),
      showTask: async id => {
        if (workspaceKey(host.getState()) === key) return host.showTask(id);
      }
    });
    panel.addEventListener('click', async event => {
      const button = event.target.closest('[data-action^="chemistry-"]');
      if (!button || !panel.contains(button)) return;
      event.preventDefault();
      event.stopPropagation();
      if (busy) return;
      busy = true;
      const controls = [...panel.querySelectorAll('button,input,select,textarea')].map(node => [node,node.disabled]);
      for (const [node] of controls) node.disabled = true;
      try { await controller.dispatch(button); }
      finally {
        for (const [node, disabled] of controls) node.disabled = disabled;
        busy = false;
      }
    });
    const entry = {panel, controller,
      async update() {
        await ready;
        if (busy || updating || !panel.isConnected) return;
        const value = state();
        const tasks = value?.tasks ?? value?.data?.tasks ?? [];
        const signature = JSON.stringify(tasks.filter(task =>
          task.state === 'complete' && (task.action?.startsWith('chemistry.') || task.action?.startsWith('source.'))
        ).map(task => task.id).sort());
        if (signature === completed) return;
        updating = true;
        try {
          await controller.update();
          if (panel.isConnected && workspaceKey(host.getState()) === key) completed = signature;
        } finally { updating = false; }
      }
    };
    desks.set(key, entry);
    ready = controller.mount(panel);
    return entry;
  }
  function mount(root) {
    const entry = desk(currentKey());
    active = entry;
    if (entry.panel.parentNode !== root) root.replaceChildren(entry.panel);
    return entry.update();
  }
  function update() {
    if (active && active === desks.get(currentKey())) return active.update();
  }
  function detach() {
    active?.panel.remove();
    active = null;
  }
  return {mount,update,detach};
}

