import {attachReceivingWaters} from './receiving_waters.mjs';

/** Receiving-water workflow on the original operator's shared extension host. */
export function attachReceivingWatersExtension(context){
  const desk=attachReceivingWaters(context);
  let node=null,lastState=null,lastSummary=null;
  function summary(state){
    const data=state?.data||{},water=data.receiving_waters||data;
    return JSON.stringify({
      workspace:state?.workspace_key,
      catalogs:water.receiving_water_catalogs||[],
      plans:water.receiving_water_plans||[],
      analyses:water.receiving_water_analyses||[],
      runs:(data.runs||[]).map(row=>[row.id,row.state,row.selection]),
      profiles:(data.profiles||[]).map(row=>[row.id,row.title]),
      scenarios:(data.scenarios||[]).map(row=>[row.id,row.title||row.spec?.title]),
      tasks:(state?.tasks||[]).filter(row=>row.action?.startsWith('receiving.water.')).map(row=>[row.id,row.state,row.result,row.error])
    });
  }
  function paint(state=context.getState()){
    if(!node)return;
    lastState=state;lastSummary=summary(state);
    desk.detach();
    node.innerHTML=desk.render();
    desk.mount(node);
  }
  function mount(target,state=context.getState()){
    if(!target||typeof target.querySelector!=='function')throw Error('Receiving waters needs the original operator content element.');
    if(node&&node!==target)desk.detach();
    node=target;paint(state);
  }
  function update(state=context.getState()){
    if(!node||state===lastState)return;
    lastState=state;
    if(summary(state)!==lastSummary)paint(state);
  }
  function detach(){
    desk.detach();node=null;lastState=null;lastSummary=null;
  }
  return {
    mount,update,detach,dispatch:desk.dispatch,
    openPlan:desk.openPlan,openAnalysis:desk.openAnalysis,openCatalog:desk.openCatalog,
    createCatalog:desk.createCatalog,createPlan:desk.createPlan,analyze:desk.analyze,
    openDelivery:desk.openDelivery,
    taskActions:desk.taskActions,deliveryFields:desk.deliveryFields,deliverySelection:desk.deliverySelection
  };
}

/** Regional soil desk using the existing source workbench controls and task queue. */
import {createSourceWorkbench} from './source_workbench.mjs';

export function createRegionalSoilDesk(host) {
  return createSourceWorkbench(host, {
    namespace:'regional-soil',
    storageKey:'upstate-regional-soil-v1',
    prepareAction:'regional-soil.prepare',
    composeAction:'regional-soil.compose',
    title:'Regional soil',
    description:'Capture the original 217-HUC soil domain, continue retained acquisition, then prepare K and coverage on the numeric 30 m land-cover grid. Completed sources stay with this study.'
  });
}

/** Original-host lifecycle binding. TokenJunkieLabs. */
import {attachScenarioAnalysis} from './scenario_analysis.mjs';

export function attachScenarioAnalysisExtension(host) {
  const desk=attachScenarioAnalysis(host);
  let node=null,pending=null;
  const workspace=()=>host.getState()?.workspace_key;
  async function applyPending(){
    const request=pending;
    if(!node||!request)return;
    if(request.workspace!==workspace()){pending=null;return;}
    pending=null;
    await desk.dispatch({dataset:{action:'analysis-open',id:request.id}});
  }
  async function open(id,options={}){
    if(!/^[0-9a-f]{64}$/.test(id||''))throw Error('Choose an original saved scenario analysis.');
    const selectedWorkspace=options.workspace_key||workspace();
    if(!selectedWorkspace||selectedWorkspace!==workspace())throw Error('Open the saved scenario analysis in its original workspace.');
    if(!(host.getState()?.data?.scenario_analyses||[]).some(row=>row.id===id))throw Error('This saved analysis is absent from the current workspace.');
    const request={id,workspace:selectedWorkspace};
    pending=request;
    try{await host.navigate('scenario-analysis');}
    catch(error){if(pending===request)pending=null;throw error;}
    if(workspace()!==selectedWorkspace){if(pending===request)pending=null;throw Error('The workspace changed while opening its saved analysis.');}
    if(node&&pending===request)await applyPending();
    return {workspace_key:selectedWorkspace,analysis_id:id};
  }
  return {
    mount(element) {
      node=element;
      node.innerHTML=desk.render();
      desk.mount(node);
      applyPending().catch(error=>host.toast?.(error.message||String(error)));
    },
    update() { if(node)desk.update(); },
    detach() { node=null;desk.detach(); },
    dispatch:button=>desk.dispatch(button),
    create:request=>desk.create(request),
    createForSourceAreas:request=>desk.createForSourceAreas(request),
    open
  };
}

